
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ms0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ms0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.784315764034945e+00, -4.688423302322636e+00, -4.554052877516531e+00, -4.367912876751603e+00, -4.114267949815235e+00, -3.776682163743834e+00, -3.342196357559152e+00, -2.808875993697594e+00, -2.195138324282116e+00, -1.529778189037761e+00, -9.539353724951269e-01, -6.602828858423840e-01, -6.086636163401937e-01, -5.218207618679149e-01, -3.627373001518114e-01, -2.117529428736541e-01, -1.031361937408214e-01, -3.584119371326401e-02, -7.735982376182987e-03, -8.696856447324899e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


